DROP TABLE IF EXISTS `river_data`;
CREATE TABLE `river_data`  (
  `id` int(0) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `period` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采样时期',
  `sampling_time` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采样时间',
  `rive_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '河流名称',
  `rive_abbreviation` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '河流简称',
  `river_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '河流编号',
  `latitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度',
  `longitude` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度',
  `plastics_splinter_type` int(0) NULL DEFAULT NULL COMMENT '塑料碎片类型',
  `plastics_fibre_type` int(0) NULL DEFAULT NULL COMMENT '塑料纤维类型',
  `plastics_grain_type` int(0) NULL DEFAULT NULL COMMENT '塑料颗粒类型',
  `plastics_membrane_type` int(0) NULL DEFAULT NULL COMMENT '塑料薄膜类型',
  `plastics_foam_type` int(0) NULL DEFAULT NULL COMMENT '塑料泡沫类型',
  `plastics_red_color` int(0) NULL DEFAULT NULL COMMENT '红色塑料',
  `plastics_black_color` int(0) NULL DEFAULT NULL COMMENT '黑色塑料',
  `plastics_white_color` int(0) NULL DEFAULT NULL COMMENT '白色塑料',
  `plastics_transparent_color` int(0) NULL DEFAULT NULL COMMENT '透明塑料',
  `plastics_blue_color` int(0) NULL DEFAULT NULL COMMENT '蓝色塑料',
  `plastics_other_color` int(0) NULL DEFAULT NULL COMMENT '其他颜色塑料',
  `fifty_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（0-50）',
  `one_hundred_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（50-100）',
  `three_hundred_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（100-300）',
  `five_hundred_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（300-500）',
  `one_thousand_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（500-1000）',
  `two_thousand_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（1000-2000）',
  `three_thousand_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（2000-3000）',
  `five_thousand_radius` int(0) NULL DEFAULT NULL COMMENT '微塑料粒径（3000-5000）',
  `plastics_total` int(0) NULL DEFAULT NULL COMMENT '微塑料总量（个）',
  `water_volume` decimal(4, 1) NULL DEFAULT NULL COMMENT '水样容量（L）',
  `plastics_abundance` decimal(6, 2) NULL DEFAULT NULL COMMENT '微塑料丰度（单位:n/l）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 81 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

